const EXPECTED_HOTTOK = 'COLE_SEU_HOTTOK_AQUI';
const input = $input.first().json;
const headers = input.headers ?? {};
const receivedHottok = String(headers['x-hotmart-hottok'] ?? '');
if (EXPECTED_HOTTOK.startsWith('COLE_')) throw new Error('Configure o HOTTOK neste node');
if (!receivedHottok || receivedHottok !== EXPECTED_HOTTOK) throw new Error('HOTTOK invalido');

const body = input.body ?? input;
if (body.event !== 'PURCHASE_APPROVED') throw new Error(`Evento ignorado: ${body.event ?? 'ausente'}`);
const data = body.data ?? {};
const purchase = data.purchase ?? {};
const buyer = data.buyer ?? {};
const product = data.product ?? {};
const transaction = String(purchase.transaction ?? '');
if (!transaction) throw new Error('Transacao Hotmart ausente');

function unixSeconds(value) {
  if (!value) return Math.floor(Date.now() / 1000);
  const numeric = Number(value);
  if (Number.isFinite(numeric)) return Math.floor(numeric > 9999999999 ? numeric / 1000 : numeric);
  const parsed = Date.parse(value);
  return Number.isNaN(parsed) ? Math.floor(Date.now() / 1000) : Math.floor(parsed / 1000);
}

const address = buyer.address ?? {};
const price = purchase.price ?? purchase.full_price ?? {};
return [{ json: {
  tracking_id: String(purchase.origin?.sck ?? purchase.sckPaymentLink ?? ''),
  transaction,
  event_time: unixSeconds(purchase.approved_date ?? purchase.order_date ?? body.creation_date),
  value: Number(price.value ?? 0),
  currency: String(price.currency_value ?? 'EUR'),
  product_id: String(product.id ?? product.external_id ?? ''),
  product_name: String(product.name ?? '101 modelli di borse all uncinetto'),
  buyer_email: String(buyer.email ?? ''),
  buyer_phone: String(buyer.checkout_phone ?? buyer.phone ?? ''),
  buyer_first_name: String(buyer.first_name ?? buyer.name?.split(' ')[0] ?? ''),
  buyer_last_name: String(buyer.last_name ?? buyer.name?.split(' ').slice(1).join(' ') ?? ''),
  buyer_city: String(address.city ?? ''),
  buyer_state: String(address.state ?? address.state_code ?? ''),
  buyer_zipcode: String(address.zipcode ?? address.zip_code ?? address.postal_code ?? ''),
  buyer_country: String(purchase.checkout_country?.iso ?? address.country_iso ?? ''),
  buyer_ucode: String(buyer.ucode ?? ''),
} }];

const sale = $('Validar Hotmart e extrair compra').first().json;
const tracking = $input.first().json ?? {};

function sha256(ascii) {
  ascii = unescape(encodeURIComponent(String(ascii)));
  const rightRotate = (value, amount) => (value >>> amount) | (value << (32 - amount));
  const maxWord = Math.pow(2, 32);
  let result = '';
  const words = [];
  const asciiBitLength = ascii.length * 8;
  let hash = sha256.h = sha256.h || [];
  let k = sha256.k = sha256.k || [];
  let primeCounter = k.length;
  const isComposite = {};
  for (let candidate = 2; primeCounter < 64; candidate++) {
    if (!isComposite[candidate]) {
      for (let i = 0; i < 313; i += candidate) isComposite[i] = candidate;
      hash[primeCounter] = (Math.pow(candidate, 0.5) * maxWord) | 0;
      k[primeCounter++] = (Math.pow(candidate, 1 / 3) * maxWord) | 0;
    }
  }
  ascii += '\x80';
  while (ascii.length % 64 - 56) ascii += '\x00';
  for (let i = 0; i < ascii.length; i++) words[i >> 2] |= ascii.charCodeAt(i) << ((3 - i) % 4) * 8;
  words[words.length] = (asciiBitLength / maxWord) | 0;
  words[words.length] = asciiBitLength;
  for (let j = 0; j < words.length;) {
    const w = words.slice(j, j += 16);
    const oldHash = hash.slice(0);
    for (let i = 0; i < 64; i++) {
      const w15 = w[i - 15], w2 = w[i - 2];
      const a = hash[0], e = hash[4];
      const temp1 = hash[7] + (rightRotate(e, 6) ^ rightRotate(e, 11) ^ rightRotate(e, 25)) + ((e & hash[5]) ^ ((~e) & hash[6])) + k[i] + (w[i] = i < 16 ? w[i] : (w[i - 16] + (rightRotate(w15, 7) ^ rightRotate(w15, 18) ^ (w15 >>> 3)) + w[i - 7] + (rightRotate(w2, 17) ^ rightRotate(w2, 19) ^ (w2 >>> 10))) | 0);
      const temp2 = (rightRotate(a, 2) ^ rightRotate(a, 13) ^ rightRotate(a, 22)) + ((a & hash[1]) ^ (a & hash[2]) ^ (hash[1] & hash[2]));
      hash = [(temp1 + temp2) | 0].concat(hash);
      hash[4] = (hash[4] + temp1) | 0;
      hash.pop();
    }
    for (let i = 0; i < 8; i++) hash[i] = (hash[i] + oldHash[i]) | 0;
  }
  for (let i = 0; i < 8; i++) for (let j = 3; j + 1; j--) {
    const b = (hash[i] >> (j * 8)) & 255;
    result += (b < 16 ? '0' : '') + b.toString(16);
  }
  return result;
}

const text = (value) => String(value ?? '').trim().toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '');
const compact = (value) => text(value).replace(/[^a-z0-9]/g, '');
const userData = {};
const addHash = (key, value, normalize = text) => { const normalized = normalize(value); if (normalized) userData[key] = [sha256(normalized)]; };
addHash('em', sale.buyer_email);
addHash('ph', sale.buyer_phone, (v) => String(v ?? '').replace(/\D/g, ''));
addHash('fn', sale.buyer_first_name, compact);
addHash('ln', sale.buyer_last_name, compact);
addHash('ct', sale.buyer_city, compact);
addHash('st', sale.buyer_state, compact);
addHash('country', sale.buyer_country, compact);
addHash('external_id', sale.tracking_id, text);
if (tracking.fbc) userData.fbc = tracking.fbc;
if (tracking.fbp) userData.fbp = tracking.fbp;
if (tracking.client_ip_address) userData.client_ip_address = tracking.client_ip_address;
if (tracking.client_user_agent) userData.client_user_agent = tracking.client_user_agent;

return [{ json: { capi: { data: [{
  event_name: 'Purchase',
  event_time: sale.event_time,
  event_id: sale.transaction,
  action_source: 'website',
  event_source_url: tracking.event_source_url || 'https://joaomota27.github.io/manualcriativo-site/it/',
  user_data: userData,
  custom_data: {
    currency: sale.currency,
    value: sale.value,
    content_ids: sale.product_id ? [sale.product_id] : [],
    contents: sale.product_id ? [{ id: sale.product_id, quantity: 1 }] : [],
    content_type: 'product',
    content_name: sale.product_name,
  },
}] } } }];

const sale = $('Validar Hotmart e extrair compra').first().json;
const output = $input.first().json;
const userData = output.capi.data[0].user_data;

