const text = (value) => String(value ?? '').trim().toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '');
const compact = (value) => text(value).replace(/[^a-z0-9]/g, '');
const dialCodes = { at:'43', be:'32', bg:'359', br:'55', ca:'1', ch:'41', cl:'56', co:'57', cy:'357', cz:'420', de:'49', dk:'45', ee:'372', es:'34', fi:'358', fr:'33', gb:'44', gr:'30', hr:'385', hu:'36', ie:'353', it:'39', lt:'370', lu:'352', lv:'371', mt:'356', mx:'52', nl:'31', no:'47', pe:'51', pl:'48', pt:'351', ro:'40', se:'46', si:'386', sk:'421', us:'1' };
function normalizePhone(phone, country) {
  let digits = String(phone ?? '').replace(/\D/g, '').replace(/^00/, '');
  const iso = text(country);
  const dial = dialCodes[iso];
  if (dial && digits && !digits.startsWith(dial)) {
    const national = iso === 'it' ? digits : digits.replace(/^0+/, '');
    digits = dial + national;
  }
  return digits;
}

const phone = normalizePhone(sale.buyer_phone, sale.buyer_country);
if (phone) userData.ph = [sha256(phone)];
const zipcode = compact(sale.buyer_zipcode);
if (zipcode) userData.zp = [sha256(zipcode)];
const externalIds = [...new Set([sale.buyer_ucode, sale.tracking_id].map(text).filter(Boolean))];
if (externalIds.length) userData.external_id = externalIds.map(sha256);

return [{ json: output }];

const output = $input.first().json;
const event = output.capi?.data?.[0];
const ids = event?.custom_data?.content_ids ?? [];
if (event && ids.map(String).includes('0')) {
  event.event_time = Math.floor(Date.now() / 1000);
}
return [{ json: output }];
